INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 19, 'theory', 'Quiz: greedy algorithms and heuristics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 0, 'In activity selection, why do we sort by end time rather than by start time?', '["An early end frees the hall as soon as possible; greed by start gets blocked by a long early event", "Sorting by end time is faster and more stable", "The start time is unreliable and often unknown", "The optimal substructure property of intervals requires it"]', 0, 'Counterexample for greed by start: a long event blocks the whole day, while skipping it allows a bunch of short ones. Activity selection is a template for dozens of problems.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 1, 'Coins 1, 3, 4 and amount 6. Why does the greedy rule “take the largest coin” lie?', '["Because the coin 4 is too large for the amount 6", "Because greed does not work on even amounts", "It hands out 4+1+1, three coins, against the right 3+3, two: arbitrary denominations break greed", "Because the amount 6 cannot be paid with this set"]', 2, 'A single new denomination broke our intuition. Greed depends not only on the problem but also on the specific data; arbitrary denominations turn making change into dynamic programming over amounts.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 2, 'The fractional knapsack is solved by greed, the whole-item one is not. What decides the fate of the method?', '["The size of the knapsack relative to the items", "Divisibility of items: being able to split a resource opens the door to simple solutions", "The order in which the items arrive in the input", "The number of distinct values among the items"]', 1, 'One switch, and the same greed goes from optimal to wrong. Before choosing an algorithm, ask what freedoms the data gives you.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 3, 'How do you check a greedy strategy in practice without writing a proof?', '["Run it on large random data and compare the running time", "Test it on sorted input data", "Compare it with another greedy algorithm on the same problem", "Look for a counterexample on a small case by hand; if one turns up, switch to dynamic programming"]', 3, 'Ten minutes of brute force on paper save weeks of analyzing a production incident. Greed and dynamic programming are two sides of the same coin.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 4, 'What is the invariant of a greedy algorithm?', '["A property the strategy preserves after every step; if it survives the first step, greed is almost certainly correct", "The minimum element from which the solution starts", "A guaranteed upper bound on the running time", "The number of steps until the first improvement of the solution"]', 0, 'In activity selection the invariant is: the hall becomes free no later than with any other choice. An invariant that breaks at the second step is itself the counterexample.');
